import java.io.*;
import java.util.*;

public class Main {
    static int n, m;
    static int[][] edges;
    static int best = 0;

    // colors[v] in [0..6], 0 means uncolored, 1..6 are dot counts
    static int[] colors;

    // For each unordered pair (a,b) with 1<=a<=b<=6 we have exactly one domino.
    // We'll map (a,b) to index in [0..20], and track usedDomino[index]
    static boolean[] usedDomino = new boolean[21];

    static int[][] dominoAB = new int[21]; // dominoAB[i][0]=a, [1]=b

    static int edgeCount;

    static int encodeDomino(int a, int b) {
        if (a > b) {
            int t = a; a = b; b = t;
        }
        int idx = 0;
        for (int i = 1; i <= 6; i++) {
            for (int j = i; j <= 6; j++) {
                if (i == a && j == b) return idx;
                idx++;
            }
        }
        return -1;
    }

    static void initDominoes() {
        int idx = 0;
        for (int a = 1; a <= 6; a++) {
            for (int b = a; b <= 6; b++) {
                dominoAB[idx] = new int[]{a, b};
                idx++;
            }
        }
    }

    static void dfs(int idx, int placed) {
        if (idx == edgeCount) {
            if (placed > best) best = placed;
            return;
        }

        // Upper bound pruning: remaining edges + placed <= best
        if (placed + (edgeCount - idx) <= best) return;

        int u = edges[idx][0];
        int v = edges[idx][1];

        int cu = colors[u];
        int cv = colors[v];

        // Try not placing any domino on this edge
        dfs(idx + 1, placed);

        // Try placing dominoes
        // We need to consider all possible (dots at u, dots at v) consistent with current colors
        for (int a = 1; a <= 6; a++) {
            if (cu != 0 && cu != a) continue;
            for (int b = 1; b <= 6; b++) {
                if (cv != 0 && cv != b) continue;

                // We can orient domino either (a,b) or (b,a), but domino type is unordered (min,max)
                int da = a, db = b;
                int idxDom = encodeDomino(da, db);
                if (idxDom == -1 || usedDomino[idxDom]) continue;

                usedDomino[idxDom] = true;

                int oldCu = cu, oldCv = cv;
                colors[u] = a;
                colors[v] = b;

                dfs(idx + 1, placed + 1);

                colors[u] = oldCu;
                colors[v] = oldCv;
                usedDomino[idxDom] = false;
            }
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        n = fs.nextInt();
        m = fs.nextInt();
        edges = new int[m][2];
        for (int i = 0; i < m; i++) {
            int a = fs.nextInt() - 1;
            int b = fs.nextInt() - 1;
            edges[i][0] = a;
            edges[i][1] = b;
        }
        edgeCount = m;
        colors = new int[n];
        initDominoes();
        dfs(0, 0);
        System.out.println(best);
    }

    // FastScanner
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
                if (c == -1) return -1;
            } while (c <= ' ');
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + c - '0';
                c = read();
            }
            return val * sign;
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static int n, m;
    static int[][] edges;
    static int best = 0;

    // For each vertex: assigned dot (0 if unassigned)
    static int[] vertexDot = new int[8]; // 1..7

    // Domino availability: for a<=b, index = (a-1)*6 - (a-1)*a/2 + (b-a)
    static boolean[] usedDomino = new boolean[21];

    // Precompute mapping from (a,b) to index
    static int[][] domIndex = new int[7][7];

    static void initDomIndex() {
        int idx = 0;
        for (int a = 1; a <= 6; a++) {
            for (int b = a; b <= 6; b++) {
                domIndex[a][b] = idx;
                domIndex[b][a] = idx;
                idx++;
            }
        }
    }

    static int getDomIndex(int a, int b) {
        return domIndex[a][b];
    }

    static void dfs(int eIdx, int placed) {
        if (placed + (m - eIdx) <= best) return;
        if (eIdx == m) {
            if (placed > best) best = placed;
            return;
        }

        int u = edges[eIdx][0];
        int v = edges[eIdx][1];

        int du = vertexDot[u];
        int dv = vertexDot[v];

        // Try to place a domino on this edge
        // Case 1: both vertices already assigned
        if (du != 0 && dv != 0) {
            if (du != dv) {
                int idx = getDomIndex(Math.min(du, dv), Math.max(du, dv));
                if (!usedDomino[idx]) {
                    usedDomino[idx] = true;
                    dfs(eIdx + 1, placed + 1);
                    usedDomino[idx] = false;
                }
            }
        } else if (du != 0 || dv != 0) {
            // Case 2: one assigned, one not
            int assigned = (du != 0) ? du : dv;
            int assignedVertex = (du != 0) ? u : v;
            int unassignedVertex = (du != 0) ? v : u;

            // We must choose a different dot for the other end
            for (int x = 1; x <= 6; x++) {
                if (x == assigned) continue;
                int idx = getDomIndex(Math.min(assigned, x), Math.max(assigned, x));
                if (usedDomino[idx]) continue;

                vertexDot[unassignedVertex] = x;
                usedDomino[idx] = true;

                dfs(eIdx + 1, placed + 1);

                usedDomino[idx] = false;
                vertexDot[unassignedVertex] = 0;
            }
        } else {
            // Case 3: both unassigned
            // Try all unordered pairs (a,b) with a!=b
            for (int a = 1; a <= 6; a++) {
                for (int b = a + 1; b <= 6; b++) {
                    int idx = getDomIndex(a, b);
                    if (usedDomino[idx]) continue;

                    // Two orientations: u->a,v->b and u->b,v->a
                    // Orientation 1
                    vertexDot[u] = a;
                    vertexDot[v] = b;
                    usedDomino[idx] = true;
                    dfs(eIdx + 1, placed + 1);
                    // Orientation 2
                    vertexDot[u] = b;
                    vertexDot[v] = a;
                    dfs(eIdx + 1, placed + 1);

                    usedDomino[idx] = false;
                    vertexDot[u] = 0;
                    vertexDot[v] = 0;
                }
            }
        }

        // Option: skip this edge
        dfs(eIdx + 1, placed);
    }

    public static void main(String[] args) throws Exception {
        initDomIndex();
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        n = Integer.parseInt(st.nextToken());
        m = Integer.parseInt(st.nextToken());
        edges = new int[m][2];
        for (int i = 0; i < m; i++) {
            st = new StringTokenizer(br.readLine());
            edges[i][0] = Integer.parseInt(st.nextToken());
            edges[i][1] = Integer.parseInt(st.nextToken());
        }

        dfs(0, 0);
        System.out.println(best);
    }
}

