        int u = edges[idx][0];
        int v = edges[idx][1];

        int valU = vertexVal[u];
        int valV = vertexVal[v];

        // Try skipping this edge
        dfs(idx + 1, placed);

        // Try placing dominoes
        for (int a = 1; a <= 6; a++) {
            for (int b = a; b <= 6; b++) {
                int di = dominoIndex(a, b);
