                        int oldU = valU, oldV = valV;
                        usedDomino[di] = true;
                        vertexVal[u] = b;
                        vertexVal[v] = a;
                        dfs(idx + 1, placed + 1);
                        vertexVal[u] = oldU;
                        vertexVal[v] = oldV;
