        if (placed + (m - idx) <= best) return;

        int u = edges[idx][0];
        int v = edges[idx][1];

        int lu = vLabel[u];
        int lv = vLabel[v];

        // Option 1: skip this edge
        dfs(idx + 1, placed);

        // Option 2: try to place domino
        // We must choose numbers a,b (1..6) with a<=b and not used
        // and consistent with vertex labels (if already assigned).
        for (int a = 1; a <= 6; a++) {
