                    int oldLu = lu, oldLv = lv;
                    vLabel[u] = a;
                    vLabel[v] = b;
                    used[a][b] = true;

                    dfs(idx + 1, placed + 1);

                    used[a][b] = false;
                    vLabel[u] = oldLu;
                    vLabel[v] = oldLv;
                }

                // orientation 2: u gets b, v gets a (only if a!=b to avoid duplicate)
                if (a != b) {
                    if ((lu == 0 || lu == b) && (lv == 0 || lv == a)) {
                        int oldLu = lu, oldLv = lv;
                        vLabel[u] = b;
                        vLabel[v] = a;
                        used[a][b] = true;

