import java.io.*;
import java.util.*;

public class Main {
    static int n, m;
    static int[][] edges;
    static int best = 0;

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        n = fs.nextInt();
        m = fs.nextInt();
        edges = new int[m][2];
        for (int i = 0; i < m; i++) {
            int a = fs.nextInt() - 1;
            int b = fs.nextInt() - 1;
            edges[i][0] = a;
            edges[i][1] = b;
        }

        // Precompute all 7^n assignments of dot counts to vertices
        int totalAssignments = 1;
        for (int i = 0; i < n; i++) totalAssignments *= 7; // 0..6
        int[] vertexDots = new int[n];

        for (int mask = 0; mask < totalAssignments; mask++) {
            int tmp = mask;
            for (int v = 0; v < n; v++) {
                vertexDots[v] = tmp % 7;
                tmp /= 7;
            }
            // vertexDots[v] in 0..6, 0 means no incoming domino, 1..6 dots
            int possibleEdges = 0;
            for (int i = 0; i < m; i++) {
                int u = edges[i][0];
                int v = edges[i][1];
                int du = vertexDots[u];
                int dv = vertexDots[v];
                if (du == 0 && dv == 0) continue;
                if (du == 0 || dv == 0) {
                    possibleEdges++;
                } else {
                    // need a domino with (du,dv) or (dv,du)
                    possibleEdges++;
                }
            }
            if (possibleEdges <= best) continue;

            // Build bipartite graph: left = edges, right = domino types (21)
            // Domino types indexed 0..20 for pairs (a,b) with 1<=a<=b<=6
            int[][] adj = new int[m][2]; // store endpoints' dots for quick use
            for (int i = 0; i < m; i++) {
                int u = edges[i][0];
                int v = edges[i][1];
                adj[i][0] = vertexDots[u];
                adj[i][1] = vertexDots[v];
            }

            List<Integer>[] g = new ArrayList[m];
            for (int i = 0; i < m; i++) g[i] = new ArrayList<>();

            for (int i = 0; i < m; i++) {
                int du = adj[i][0];
                int dv = adj[i][1];
                if (du == 0 && dv == 0) continue;
                if (du == 0 || dv == 0) {
                    int d = du != 0 ? du : dv;
                    int idx = dominoIndex(d, d);
                    g[i].add(idx);
                } else {
                    int a = du, b = dv;
                    int idx1 = dominoIndex(Math.min(a, b), Math.max(a, b));
                    g[i].add(idx1);
                }
            }

            int match = maxBipartiteMatching(g, 21);
            if (match > best) best = match;
        }

        System.out.println(best);
    }

    // Map (a,b) with 1<=a<=b<=6 to index 0..20
    static int dominoIndex(int a, int b) {
        int idx = 0;
        for (int i = 1; i <= 6; i++) {
            for (int j = i; j <= 6; j++) {
                if (i == a && j == b) return idx;
                idx++;
            }
        }
        return -1;
    }

    static int maxBipartiteMatching(List<Integer>[] g, int rightSize) {
        int m = g.length;
        int[] matchR = new int[rightSize];
        Arrays.fill(matchR, -1);
        int res = 0;
        for (int u = 0; u < m; u++) {
            boolean[] vis = new boolean[rightSize];
            if (dfs(u, g, matchR, vis)) res++;
        }
        return res;
    }

    static boolean dfs(int u, List<Integer>[] g, int[] matchR, boolean[] vis) {
        for (int v : g[u]) {
            if (vis[v]) continue;
            vis[v] = true;
            if (matchR[v] == -1 || dfs(matchR[v], g, matchR, vis)) {
                matchR[v] = u;
                return true;
            }
        }
        return false;
    }

    // Fast scanner
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
                if (c == -1) return -1;
            } while (c <= ' ');
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + c - '0';
                c = read();
            }
            return val * sign;
        }
    }
}

