public class Main {
    static int n, m;
    static int[][] edges; // [m][2]
    static int best = 0;

    // dominoUsed[a][b] where 1<=a<=b<=6
    static boolean[][] dominoUsed = new boolean[7][7];

    // vertex label 0..6 meaning number of dots, 0 = unlabeled
    static int[] label;

    static void dfs(int idx, int usedCount) {
        if (idx == m) {
            if (usedCount > best) best = usedCount;
            return;
        }

        // Prune: remaining edges + usedCount <= best
        if (usedCount + (m - idx) <= best) return;

        int u = edges[idx][0];
        int v = edges[idx][1];

        int lu = label[u];
        int lv = label[v];

        // Try to place a domino on this edge
        // Cases for labels:
        // lu, lv in {0..6}, 0 means unlabeled

        // We'll try all possible (a,b) with 1<=a<=b<=6 and available
        // but constrained by existing labels.

        // Determine allowed pairs
        for (int a = 1; a <= 6; a++) {
            for (int b = a; b <= 6; b++) {
                if (dominoUsed[a][b]) continue;

                // Two orientations: (a->u, b->v) and (b->u, a->v)
                // But if a==b, both orientations are same.
                // Orientation 1:
                if (canAssign(lu, a) && canAssign(lv, b)) {
                    int oldLu = lu, oldLv = lv;
                    boolean changedU = false, changedV = false;

                    if (lu == 0) {
                        label[u] = a;
                        changedU = true;
                    }
                    if (lv == 0) {
                        label[v] = b;
                        changedV = true;
                    }

                    dominoUsed[a][b] = true;
                    dfs(idx + 1, usedCount + 1);
                    dominoUsed[a][b] = false;

                    if (changedU) label[u] = oldLu;
                    if (changedV) label[v] = oldLv;
                }

                if (a != b) {
                    // Orientation 2: swap
                    if (canAssign(lu, b) && canAssign(lv, a)) {
                        int oldLu = lu, oldLv = lv;
                        boolean changedU = false, changedV = false;

                        if (lu == 0) {
                            label[u] = b;
                            changedU = true;
