                        dfs(idx + 1, usedCount + 1);
                        dominoUsed[a][b] = false;

                        if (changedU) label[u] = oldLu;
                        if (changedV) label[v] = oldLv;
                    }
                }
            }
        }

        // Option: skip this edge
        dfs(idx + 1, usedCount);
    }

    static boolean canAssign(int currentLabel, int newLabel) {
        return currentLabel == 0 || currentLabel == newLabel;
    }

