import java.io.*;
import java.util.*;

public class Main {
    static int n, m;
    static int[][] edges;
    static int best = 0;

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        n = fs.nextInt();
        m = fs.nextInt();
        edges = new int[m][2];
        for (int i = 0; i < m; i++) {
            int a = fs.nextInt() - 1;
            int b = fs.nextInt() - 1;
            edges[i][0] = a;
            edges[i][1] = b;
        }

        // Precompute all 7^n assignments of dot counts to vertices
        int totalAssign = 1;
        for (int i = 0; i < n; i++) totalAssign *= 7; // 0..6, where 0 means "unused"
        int[] dots = new int[n];

        for (int mask = 0; mask < totalAssign; mask++) {
            int tmp = mask;
            for (int v = 0; v < n; v++) {
                dots[v] = tmp % 7;
                tmp /= 7;
            }
            // Skip assignments where all vertices are 0 (no dots)
            boolean any = false;
            for (int v = 0; v < n; v++) {
                if (dots[v] != 0) {
                    any = true;
                    break;
                }
            }
            if (!any) continue;

            int val = solveForAssignment(dots);
            if (val > best) best = val;
        }

        System.out.println(best);
    }

    // For a fixed assignment of dots to vertices, compute maximum number of edges
    // that can be covered with distinct domino types.
    static int solveForAssignment(int[] dots) {
        // Build list of candidate edges with their (a,b) dot pair
        int k = 0;
        int[][] cand = new int[m][3]; // u, v, pairIndex
        for (int i = 0; i < m; i++) {
            int u = edges[i][0];
            int v = edges[i][1];
            int du = dots[u];
            int dv = dots[v];
            if (du == 0 || dv == 0) continue; // cannot use this edge
            int a = Math.min(du, dv);
            int b = Math.max(du, dv);
            int idx = pairIndex(a, b);
            cand[k][0] = u;
            cand[k][1] = v;
            cand[k][2] = idx;
            k++;
        }
        if (k == 0) return 0;

        // Backtracking over candidate edges with 21-bit mask for used domino types
        return backtrack(cand, k, 0, 0, 0);
    }

    // pairIndex for 1<=a<=b<=6, map to 0..20
    static int pairIndex(int a, int b) {
        // number of pairs with first < a: sum_{i=1}^{a-1} (7 - i) = (a-1)*(8-a)/2
        int offset = (a - 1) * (8 - a) / 2;
        return offset + (b - a);
    }

    static int backtrack(int[][] cand, int k, int pos, int usedMask, int count) {
        if (pos == k) return count;
        int remaining = k - pos;
        if (count + remaining <= best) {
            // global pruning using best; but best is global over all assignments,
            // here we only need local best, so we skip this pruning
        }
        // Option 1: skip this edge
        int bestLocal = count;
        bestLocal = Math.max(bestLocal, backtrack(cand, k, pos + 1, usedMask, count));

        // Option 2: use this edge if domino type not used
        int idx = cand[pos][2];
        if ((usedMask & (1 << idx)) == 0) {
            bestLocal = Math.max(bestLocal,
                    backtrack(cand, k, pos + 1, usedMask | (1 << idx), count + 1));
        }
        return bestLocal;
    }

    // Fast scanner
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
                if (c == -1) return -1;
            } while (c <= ' ');
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + c - '0';
                c = read();
            }
            return val * sign;
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static int n, m;
    static int[][] edges; // [m][2]
    static int best = 0;

    // dominoUsed[a][b] where 1<=a<=b<=6
    static boolean[][] dominoUsed = new boolean[7][7];

    // vertex label 1..n, 0 means unlabeled, 1..6 assigned
    static int[] label;

    static void dfs(int idx, int placed) {
        if (idx == m) {
            if (placed > best) best = placed;
            return;
        }

        // upper bound: remaining edges + placed
        if (placed + (m - idx) <= best) return;

        int u = edges[idx][0];
        int v = edges[idx][1];

        int lu = label[u];
        int lv = label[v];

        // Try to place a domino
        // We will iterate over all possible (x,y) with 1<=x<=y<=6
        for (int x = 1; x <= 6; x++) {
            for (int y = x; y <= 6; y++) {
                if (dominoUsed[x][y]) continue;

                // Two orientations: (x->u, y->v) and (y->u, x->v)
                // orientation 1
                if (canPlace(u, v, x, y)) {
                    boolean needAssignU = (lu == 0);
                    boolean needAssignV = (lv == 0);
                    int oldLu = lu, oldLv = lv;

                    dominoUsed[x][y] = true;
                    if (needAssignU) label[u] = x;
                    if (needAssignV) label[v] = y;

                    dfs(idx + 1, placed + 1);

                    if (needAssignU) label[u] = oldLu;
                    if (needAssignV) label[v] = oldLv;
                    dominoUsed[x][y] = false;
                }

                // orientation 2, avoid duplicate when x==y
                if (x != y && canPlace(u, v, y, x)) {
                    boolean needAssignU = (lu == 0);
                    boolean needAssignV = (lv == 0);
                    int oldLu = lu, oldLv = lv;

                    dominoUsed[x][y] = true;
                    if (needAssignU) label[u] = y;
                    if (needAssignV) label[v] = x;

                    dfs(idx + 1, placed + 1);

                    if (needAssignU) label[u] = oldLu;
                    if (needAssignV) label[v] = oldLv;
                    dominoUsed[x][y] = false;
                }
            }
        }

        // Option: skip this edge
        dfs(idx + 1, placed);
    }

    static boolean canPlace(int u, int v, int dotU, int dotV) {
        int lu = label[u];
        int lv = label[v];
        if (lu != 0 && lu != dotU) return false;
        if (lv != 0 && lv != dotV) return false;
        return true;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        n = fs.nextInt();
        m = fs.nextInt();
        edges = new int[m][2];
        for (int i = 0; i < m; i++) {
            int a = fs.nextInt();
            int b = fs.nextInt();
            edges[i][0] = a;
            edges[i][1] = b;
        }
        label = new int[n + 1];

        dfs(0, 0);

        System.out.println(best);
    }

    // Fast scanner
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
                if (c == -1) return -1;
            } while (c <= ' ');
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
